module convolutional_encoder (
    input clk,
    input reset,
    input [0:0] data_in,
    output reg [1:0] data_out
);
    reg [2:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 3'b000;
            data_out <= 2'b00;
        end else begin
            shift_reg <= {shift_reg[1:0], data_in};
            data_out <= {shift_reg[2] ^ shift_reg[1] ^ data_in, shift_reg[2] ^ shift_reg[0]};
        end
    end
endmodule

