                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: a_inv=%h, b_inv=%h, c_inv=%h, d_inv=%h",
                         expected_a_inv, expected_b_inv, expected_c_inv, expected_d_inv);
