`timescale 1ns/1ps

module sram_cell_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg d;
    reg wen;
    wire q;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    sram_cell dut (
        .clk(clk),
        .d(d),
        .wen(wen),
        .q(q)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            @(posedge clk);
            wen <= 1;
            d <= 0;
            @(posedge clk);
            wen <= 0;
            d <= 0;
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Write '1' and verify output", test_num);
            reset_dut();

            @(posedge clk);
            wen <= 1;
            d <= 1;
            @(posedge clk);
            wen <= 0;

            #2;
            #1;

            check_outputs(1);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Write '0' and verify output", test_num);
            reset_dut();


            @(posedge clk);
            wen <= 1;
            d <= 1;
            @(posedge clk);


            wen <= 1;
            d <= 0;
            @(posedge clk);
            wen <= 0;

            #2;
            #1;

            check_outputs(0);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Retention test - Hold '1' while d changes", test_num);
            reset_dut();


            @(posedge clk);
            wen <= 1;
            d <= 1;
            @(posedge clk);


            wen <= 0;
            d <= 0;
            @(posedge clk);
            @(posedge clk);

            #2;
            #1;

            check_outputs(1);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Retention test - Hold '0' while d changes", test_num);
            reset_dut();


            @(posedge clk);
            wen <= 1;
            d <= 1;
            @(posedge clk);
            wen <= 1;
            d <= 0;
            @(posedge clk);


            wen <= 0;
            d <= 1;
            @(posedge clk);

            #2;
            #1;

            check_outputs(0);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Rapid toggle write test", test_num);
            reset_dut();

            @(posedge clk);
            wen <= 1; d <= 1;
            @(posedge clk);
            wen <= 1; d <= 0;
            @(posedge clk);
            wen <= 1; d <= 1;
            @(posedge clk);
            wen <= 0;

            #2;
            #1;

            check_outputs(1);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("sram_cell Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_q;
        begin
            if (expected_q === (expected_q ^ q ^ expected_q)) begin
                $display("PASS");
                $display("  Outputs: q=%b",
                         q);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: q=%b",
                         expected_q);
                $display("  Got:      q=%b",
                         q);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, d, wen, q);
    end

endmodule

